function validateTaxonomy(taxonomy) {
  if (!Array.isArray(taxonomy) || !taxonomy.length) throw new Error('Provide a nonempty category taxonomy.');
  const ids = new Set();
  return taxonomy.map(category => {
    if (!category || !Number.isSafeInteger(category.id) || category.id < 1 || typeof category.name !== 'string' || !category.name.trim()) {
      throw new Error('Each category needs a positive integer ID and nonempty name.');
    }
    if (ids.has(category.id)) throw new Error('Category IDs must be unique.');
    ids.add(category.id);
    return { id: category.id, name: category.name.trim() };
  });
}

const prepare = function prepareTaxonomy({ taxonomyJson }) {
  if (typeof taxonomyJson !== 'string') throw new Error('Provide the category taxonomy as JSON text.');
  let parsed;
  try { parsed = JSON.parse(taxonomyJson); } catch { throw new Error('The category taxonomy must be valid JSON.'); }
  return { taxonomy: validateTaxonomy(parsed) };
}

return [{json:prepare($input.first().json)}];

function normalizePosts(posts) {
  if (!Array.isArray(posts)) throw new Error('WordPress must return a post array.');
  const ids = new Set();
  return posts.map(post => {
    if (!post || !Number.isSafeInteger(post.id) || post.id < 1 || typeof post.title?.rendered !== 'string') throw new Error('Every WordPress post needs an ID and rendered title.');
    if (ids.has(post.id)) throw new Error('Repeated post IDs were returned; keep the site stable while listing and try again.');
    ids.add(post.id);
    return { id: post.id, title: post.title.rendered };
  });
}


const raw=$input.all().map(item=>item.json);const posts=normalizePosts(raw.length===1&&Object.keys(raw[0]).length===0?[]:raw);const taxonomy=$('Validate Category Taxonomy').first().json.taxonomy;const categoryList=taxonomy.map(category=>category.id+' = '+category.name).join('\n');return posts.length?posts.map(post=>({json:{...post,categoryList,empty:false}})):[{json:{empty:true}}];

const validate = function validateCategory({ id, completion, allowedIds }) {
  if (typeof completion !== 'string' || !/^[1-9]\d*$/.test(completion.trim())) throw new Error('The model must return exactly one positive category ID.');
  const categoryId = Number(completion.trim());
  if (!Number.isSafeInteger(categoryId) || !allowedIds.includes(categoryId)) throw new Error('The model selected a category outside the configured taxonomy.');
  if (!Number.isSafeInteger(id) || id < 1) throw new Error('The source post ID is invalid.');
  return { id, categoryId };
}

const posts=$('Prepare Post Titles').all().map(item=>item.json),items=$input.all(),allowedIds=$('Validate Category Taxonomy').first().json.taxonomy.map(category=>category.id);if(items.length!==posts.length)throw new Error('Classification count differs from the post count.');return items.map((item,index)=>({json:validate({id:posts[index].id,completion:item.json.text,allowedIds}),pairedItem:{item:index}}));
